import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Shield, Terminal, History, User, LogOut, Info, Cpu, Layers } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const navigate = useNavigate();
  const location = useLocation();

  // Handles smooth scrolling to section anchors on the landing page
  const scrollToSection = (sectionId) => {
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      const element = document.getElementById(sectionId);
      if (element) element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '14px 32px',
      backgroundColor: 'rgba(10, 13, 18, 0.9)',
      backdropFilter: 'blur(10px)',
      borderBottom: '1px solid var(--border-glow)',
      position: 'sticky',
      top: 0,
      zIndex: 1000
    }}>
      <div 
        onClick={() => scrollToSection('hero-section')} 
        style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer' }}
      >
        <Shield size={26} color="var(--accent-cyan)" />
        <span style={{ fontSize: '18px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
          NET_SENTINEL // SOC
        </span>
      </div>

      {/* Header Navigation Links */}
      <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
        <button 
          onClick={() => scrollToSection('hero-section')} 
          className="cyber-button" 
          style={{ padding: '6px 12px', fontSize: '12px', border: 'none', background: 'transparent' }}
        >
          <Info size={13} /> TOP
        </button>

        <button 
          onClick={() => scrollToSection('about-section')} 
          className="cyber-button" 
          style={{ padding: '6px 12px', fontSize: '12px', border: 'none', background: 'transparent' }}
        >
          <Cpu size={13} /> ABOUT PROJECT
        </button>

        <button 
          onClick={() => scrollToSection('modules-section')} 
          className="cyber-button" 
          style={{ padding: '6px 12px', fontSize: '12px', border: 'none', background: 'transparent' }}
        >
          <Layers size={13} /> TOOL MODULES
        </button>

        <Link to="/dashboard" className="cyber-button" style={{ padding: '8px 14px', fontSize: '12px' }}>
          <Terminal size={14} /> CONSOLE
        </Link>
        
        <Link to="/history" className="cyber-button" style={{ padding: '8px 14px', fontSize: '12px' }}>
          <History size={14} /> LOGS
        </Link>

        {user ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginLeft: '10px' }}>
            <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '12px' }}>
              [{user.name}]
            </span>
            <button className="cyber-button" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '6px 10px' }}>
              <LogOut size={14} />
            </button>
          </div>
        ) : (
          <Link to="/login" className="cyber-button" style={{ padding: '8px 16px', fontSize: '12px', backgroundColor: 'rgba(0, 243, 255, 0.1)' }}>
            <User size={14} /> LOGIN / SIGNUP
          </Link>
        )}
      </div>
    </nav>
  );
}
